-- P05 · REGISTO DE BASE do staging, IMEDIATAMENTE antes de instalar (depois de P00–P04 aprovados).
-- Substituir __EMAIL_AUTORIZADO__ como no P04. Copiar as 7 impressões (B01…B07) para os marcadores
-- __P05_B0x_…__ do Q03 e do Q04. Correr P05, Q03 e Q04 na MESMA ferramenta/sessão de leitura
-- (o texto de USING/WITH CHECK e dos tipos depende do search_path; diferenças => REPROVADO, nunca aprovado).
-- Lê auth.identities: sem permissão => ERRO => BLOQUEIO (B11).
-- REGISTO DE BASE — NÃO é uma verificação e não "aprova" nada. Só leitura: um único SELECT.
-- Cada linha devolve uma impressão sha256 e a COBERTURA (nº de linhas impressas). Impressão nula
-- ou cobertura diferente da exigida => a consulta TERMINA EM ERRO com "REGISTO INVÁLIDO: …".
WITH alvo AS (SELECT lower('__EMAIL_AUTORIZADO__') AS email),
u AS (SELECT au.id, lower(au.email) AS email, to_jsonb(au) AS j FROM auth.users au, alvo WHERE lower(au.email) = alvo.email),
r AS (SELECT ur.id, ur.user_id, ur.role, ur.created_at FROM public.user_roles ur WHERE ur.user_id IN (SELECT id FROM u)),
b(id, registo, impressao, cobertura, cobertura_ok, cobertura_exigida) AS (
  SELECT 'B01'::text, 'conta do proprietário em auth.users (campos estáveis; ver OWNER-ACCOUNT.md)'::text, (encode(sha256(convert_to((SELECT string_agg(coalesce(u.j ->> 'id', '~') || '|' || coalesce(u.j ->> 'email', '~') || '|' || coalesce(u.j ->> 'phone', '~') || '|' || coalesce(u.j ->> 'aud', '~') || '|' || coalesce(u.j ->> 'role', '~') || '|' || coalesce(u.j ->> 'is_sso_user', '~') || '|' || coalesce(u.j ->> 'is_anonymous', '~') || '|' || coalesce(u.j ->> 'raw_app_meta_data', '~') || '|' || coalesce(extract(epoch FROM (u.j ->> 'email_confirmed_at')::timestamptz)::text, '~') || '|' || coalesce(extract(epoch FROM (u.j ->> 'phone_confirmed_at')::timestamptz)::text, '~') || '|' || coalesce(extract(epoch FROM (u.j ->> 'created_at')::timestamptz)::text, '~') || '|' || coalesce(extract(epoch FROM (u.j ->> 'banned_until')::timestamptz)::text, '~') || '|' || coalesce(extract(epoch FROM (u.j ->> 'deleted_at')::timestamptz)::text, '~'), E'\n' ORDER BY u.id) FROM u), 'UTF8')), 'hex'))::text, ((SELECT count(*) FROM u))::bigint, ((SELECT count(*) FROM u) = 1 AND (SELECT count(*) FROM auth.users) = 1)::boolean, '1 (e 1 conta no total)'::text
  UNION ALL SELECT 'B02'::text, 'identidades da conta em auth.identities (sem last_sign_in_at/updated_at)'::text, (encode(sha256(convert_to((SELECT string_agg(coalesce(to_jsonb(i) ->> 'id', '~') || '|' || coalesce(to_jsonb(i) ->> 'provider', '~') || '|' || coalesce(to_jsonb(i) ->> 'provider_id', '~') || '|' || coalesce(to_jsonb(i) ->> 'user_id', '~') || '|' || coalesce(extract(epoch FROM (to_jsonb(i) ->> 'created_at')::timestamptz)::text, '~') || '|' || coalesce(i.identity_data ->> 'sub', '~') || '|' || coalesce(lower(i.identity_data ->> 'email'), '~'), E'\n' ORDER BY i.provider, to_jsonb(i) ->> 'id') FROM auth.identities i WHERE i.user_id IN (SELECT id FROM u)), 'UTF8')), 'hex'))::text, ((SELECT count(*) FROM auth.identities i WHERE i.user_id IN (SELECT id FROM u)))::bigint, ((SELECT count(*) FROM auth.identities i WHERE i.user_id IN (SELECT id FROM u)) >= 1 AND (SELECT count(*) FROM auth.identities) = (SELECT count(*) FROM auth.identities i WHERE i.user_id IN (SELECT id FROM u)))::boolean, '>= 1 e todas desta conta'::text
  UNION ALL SELECT 'B03'::text, 'todas as linhas de user_roles (id, user_id, role, created_at)'::text, (encode(sha256(convert_to((SELECT string_agg(ur.id::text || '|' || ur.user_id::text || '|' || ur.role::text || '|' || extract(epoch FROM ur.created_at)::text, E'\n' ORDER BY ur.id) FROM public.user_roles ur), 'UTF8')), 'hex'))::text, ((SELECT count(*) FROM public.user_roles))::bigint, ((SELECT count(*) FROM public.user_roles) = 1)::boolean, '1'::text
  UNION ALL SELECT 'B04'::text, 'políticas de staging_notes/user_roles: nome, tipo, papéis, comando, USING e WITH CHECK'::text, (encode(sha256(convert_to((SELECT string_agg(tablename::text || '|' || policyname::text || '|' || permissive::text || '|' || array_to_string(roles, '+') || '|' || cmd::text || '|' || coalesce(qual, '~') || '|' || coalesce(with_check, '~'), E'\n' ORDER BY tablename, policyname) FROM pg_policies WHERE schemaname = 'public' AND tablename IN ('staging_notes', 'user_roles')), 'UTF8')), 'hex'))::text, ((SELECT count(*) FROM pg_policies WHERE schemaname = 'public' AND tablename IN ('staging_notes', 'user_roles')))::bigint, ((SELECT count(*) FROM pg_policies WHERE schemaname = 'public' AND tablename IN ('staging_notes', 'user_roles')) = 2)::boolean, '2'::text
  UNION ALL SELECT 'B05'::text, 'has_role/has_staging_access: assinatura, retorno, linguagem, SECURITY DEFINER, volatilidade, strict, leakproof, paralelo, search_path, dono, permissões, sha256 do corpo'::text, (encode(sha256(convert_to((SELECT string_agg(p.proname::text || '|' || pg_get_function_identity_arguments(p.oid) || '|' || p.prorettype::regtype::text || '|' || l.lanname::text || '|' || p.prosecdef::text || '|' || p.provolatile::text || '|' || p.proisstrict::text || '|' || p.proleakproof::text || '|' || p.proparallel::text || '|' || coalesce(array_to_string(p.proconfig, ','), '~') || '|' || pg_get_userbyid(p.proowner)::text || '|' || coalesce(p.proacl::text, '~') || '|' || encode(sha256(convert_to(p.prosrc, 'UTF8')), 'hex'), E'\n' ORDER BY p.proname) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace JOIN pg_language l ON l.oid = p.prolang WHERE n.nspname = 'public' AND p.proname IN ('has_role', 'has_staging_access')), 'UTF8')), 'hex'))::text, ((SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace JOIN pg_language l ON l.oid = p.prolang WHERE n.nspname = 'public' AND p.proname IN ('has_role', 'has_staging_access')))::bigint, ((SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace JOIN pg_language l ON l.oid = p.prolang WHERE n.nspname = 'public' AND p.proname IN ('has_role', 'has_staging_access')) = 2)::boolean, '2'::text
  UNION ALL SELECT 'B06'::text, 'staging_notes/user_roles: tipo, dono, permissões de tabela e de coluna, RLS e FORCE RLS'::text, (encode(sha256(convert_to((SELECT string_agg(c.relname::text || '|' || c.relkind::text || '|' || pg_get_userbyid(c.relowner)::text || '|' || coalesce(c.relacl::text, '~') || '|' || c.relrowsecurity::text || '|' || c.relforcerowsecurity::text || '|' || coalesce((SELECT string_agg(a.attname::text || '=' || a.attacl::text, ',' ORDER BY a.attname) FROM pg_attribute a WHERE a.attrelid = c.oid AND a.attacl IS NOT NULL AND a.attname <> 'created_by'), '~'), E'\n' ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relname IN ('staging_notes', 'user_roles')), 'UTF8')), 'hex'))::text, ((SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relname IN ('staging_notes', 'user_roles')))::bigint, ((SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relname IN ('staging_notes', 'user_roles')) = 2)::boolean, '2'::text
  UNION ALL SELECT 'B07'::text, 'tipo app_role: dono, permissões e natureza (os valores mudam de propósito; ver Q04-12)'::text, (encode(sha256(convert_to((SELECT string_agg(pg_get_userbyid(t.typowner)::text || '|' || coalesce(t.typacl::text, '~') || '|' || t.typtype::text, E'\n') FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace WHERE n.nspname = 'public' AND t.typname = 'app_role'), 'UTF8')), 'hex'))::text, ((SELECT count(*) FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace WHERE n.nspname = 'public' AND t.typname = 'app_role'))::bigint, ((SELECT count(*) FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace WHERE n.nspname = 'public' AND t.typname = 'app_role') = 1)::boolean, '1'::text
),
v AS (SELECT count(*) AS n, string_agg(id || ' cobertura=' || coalesce(cobertura::text, 'NULL') || ' impressao=' || coalesce(left(impressao, 12), 'NULL'), ' | ' ORDER BY id) FILTER (WHERE impressao IS NULL OR impressao !~ '^[0-9a-f]{64}$' OR cobertura_ok IS NOT TRUE) AS falhas FROM b)
SELECT b.id, b.registo, b.impressao, b.cobertura, b.cobertura_exigida,
       CASE WHEN v.n <> 7 THEN ('REGISTO INVÁLIDO: ' || v.n::text || ' linhas')::int::text
            WHEN v.falhas IS NULL THEN 'REGISTO VÁLIDO (copiar as impressões para o Q03/Q04)'
            ELSE ('REGISTO INVÁLIDO: ' || v.falhas)::int::text END AS resultado
  FROM b CROSS JOIN v ORDER BY b.id;
